#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> pathsWithMaxScore(std::vector<std::string>& board) {
        int MOD = 1000000007;
        int n = board.size();
        std::vector<std::vector<int>> dpScore(n, std::vector<int>(n, -1));
        std::vector<std::vector<int>> dpCount(n, std::vector<int>(n, 0));
        dpScore[n - 1][n - 1] = 0;
        dpCount[n - 1][n - 1] = 1;
        int dirs[3][2] = {{-1, 0}, {0, -1}, {-1, -1}};
        for (int r = n - 1; r >= 0; --r) {
            for (int c = n - 1; c >= 0; --c) {
                if (board[r][c] == 'X' || dpScore[r][c] == -1) continue;
                int curScore = dpScore[r][c];
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] != 'X') {
                        int addVal = (board[nr][nc] == 'E') ? 0 : (board[nr][nc] - '0');
                        int nxtScore = curScore + addVal;
                        if (nxtScore > dpScore[nr][nc]) {
                            dpScore[nr][nc] = nxtScore;
                            dpCount[nr][nc] = dpCount[r][c];
                        } else if (nxtScore == dpScore[nr][nc]) {
                            dpCount[nr][nc] = (dpCount[nr][nc] + dpCount[r][c]) % MOD;
                        }
                    }
                }
            }
        }
        if (dpScore[0][0] == -1) return {0, 0};
        return {dpScore[0][0], dpCount[0][0]};
    }
};

class Solution {
    public int[] pathsWithMaxScore(java.util.List<String> board) {
        int MOD = 1000000007;
        int n = board.size();
        int[][] dpScore = new int[n][n];
        int[][] dpCount = new int[n][n];
        for (int[] row : dpScore) java.util.Arrays.fill(row, -1);
        dpScore[n - 1][n - 1] = 0;
        dpCount[n - 1][n - 1] = 1;
        int[][] dirs = {{-1, 0}, {0, -1}, {-1, -1}};
        for (int r = n - 1; r >= 0; r--) {
            for (int c = n - 1; c >= 0; c--) {
                if (board.get(r).charAt(c) == 'X' || dpScore[r][c] == -1) continue;
                int curScore = dpScore[r][c];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && board.get(nr).charAt(nc) != 'X') {
                        char ch = board.get(nr).charAt(nc);
                        int addVal = (ch == 'E') ? 0 : (ch - '0');
                        int nxtScore = curScore + addVal;
                        if (nxtScore > dpScore[nr][nc]) {
                            dpScore[nr][nc] = nxtScore;
                            dpCount[nr][nc] = dpCount[r][c];
                        } else if (nxtScore == dpScore[nr][nc]) {
                            dpCount[nr][nc] = (dpCount[nr][nc] + dpCount[r][c]) % MOD;
                        }
                    }
                }
            }
        }
        if (dpScore[0][0] == -1) return new int[]{0, 0};
        return new int[]{dpScore[0][0], dpCount[0][0]};
    }
}

var pathsWithMaxScore = function(board) {
    const MOD = 1000000007;
    const n = board.length;
    const dpScore = Array.from({ length: n }, () => new Int32Array(n).fill(-1));
    const dpCount = Array.from({ length: n }, () => new Int32Array(n));
    dpScore[n - 1][n - 1] = 0;
    dpCount[n - 1][n - 1] = 1;
    const dirs = [[-1, 0], [0, -1], [-1, -1]];
    for (let r = n - 1; r >= 0; r--) {
        for (let c = n - 1; c >= 0; c--) {
            if (board[r][c] === "X" || dpScore[r][c] === -1) continue;
            const curScore = dpScore[r][c];
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && board[nr][nc] !== "X") {
                    const addVal = (board[nr][nc] === "E") ? 0 : (board[nr][nc].charCodeAt(0) - 48);
                    const nxtScore = curScore + addVal;
                    if (nxtScore > dpScore[nr][nc]) {
                        dpScore[nr][nc] = nxtScore;
                        dpCount[nr][nc] = dpCount[r][c];
                    } else if (nxtScore === dpScore[nr][nc]) {
                        dpCount[nr][nc] = (dpCount[nr][nc] + dpCount[r][c]) % MOD;
                    }
                }
            }
        }
    }
    if (dpScore[0][0] === -1) return [0, 0];
    return [dpScore[0][0], dpCount[0][0]];
};
